import{z as A,x as B,o as E,c as d,q as r,j as i,D as t,d as s,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"关键路径调度","description":"","frontmatter":{"title":"关键路径调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/critical-path-scheduling.md","filePath":"cs/critical-path-scheduling.md","lastUpdated":1791063341000}'),p={name:"cs/critical-path-scheduling.md"};function c(h,a,u,m,D,C){const l=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="关键路径调度" tabindex="-1">关键路径调度 <a class="header-anchor" href="#关键路径调度" aria-label="Permalink to &quot;关键路径调度&quot;">​</a></h1><div class="epigraph"><p>DAG 上最长加权路径决定块的下界周期。优先级让关键路径上的节点先发，避免闲置把下界再拉长。</p><footer>—— 据 Hu 的表调度传统；Hennessy and Gross；龙书指令调度；组成课[关键路径](/cs/critical-path) 对照整理</footer></div><p>上一课<a href="/cs/software-pipelining">软件流水</a>用 RecMII（环上关键）。块内同样：无环 DAG 的关键路径长度是表调度的下界。缺口是把组成课门级关键路径的直觉<strong>搬到指令 DAG</strong>（延迟为边权）。本课钉高度函数与为何「先发关键」，不写时钟树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>就绪表若总发短延迟、非关键指令，关键节点被挤到后面，总拍数超过下界。优先级：节点高度 = 到出口的最长路径。缺口是<strong>这个下界与启发式</strong>，不是模 II。</p><p>寄存器压力：全按高度可能瞬时活太多，需混合优先级。</p><h3 id="指令关键路径不是-sta-的门延迟" tabindex="-1">指令关键路径不是 STA 的门延迟 <a class="header-anchor" href="#指令关键路径不是-sta-的门延迟" aria-label="Permalink to &quot;指令关键路径不是 STA 的门延迟&quot;">​</a></h3><p>STA 是芯片；这里边权是指令延迟表（ISA/微架构模型）。模型错则调度错，不是硅上时序违例。</p><p><span class="marginnote">经典 list scheduling 用 height/latency。组成课 critical-path 是电路。本课明确不重画时钟树。</span></p><p><span class="marginnote">术语翻译：节点的高度就是「从这里走到 DAG 出口、最长还要多久」。把每个节点这条「到终点还剩多远」算出来当优先级——高度越大越急，先发它才不拖累整体。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 DAG 汇点反向最长路。就绪时选高度最大。打破平局：延迟大、或扇出大。与资源（单端口乘）结合：资源可用才就绪。</p>',12)),(E(),i(o,null,{default:t(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DAG%5B%22%E6%8C%87%E4%BB%A4%20DAG%22%5D%20--%3E%20H%5B%22%E9%AB%98%E5%BA%A6%20%3D%20%E6%9C%80%E9%95%BF%E8%B7%AF%22%5D%0A%20%20H%20--%3E%20LIST%5B%22%E8%A1%A8%E8%B0%83%E5%BA%A6%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20LIST%20--%3E%20LB%5B%22%E6%8E%A5%E8%BF%91%E4%B8%8B%E7%95%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：下界像「关键路径上一串人挨个过安检所需的时间」。可要是两个最急的人偏偏都需要人工开箱（乘法器只有一个），就得有人等——队伍实际长度于是超过理想值，这就是资源冲突让下界不可达。")],-1)),a[4]||(a[4]=e("p",null,"与软件流水：RecMII 就是环上关键路径 / 迭代。同一度量，拓扑有环。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"下界不可达：资源冲突。启发式无保证。不要把关键路径当「必须连续发射」，中间可插独立指令填槽——那正是表调度的工作。",-1)),(E(),i(o,null,{default:t(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCHED%5B%22%E9%AB%98%E5%BA%A6%E4%BC%98%E5%85%88%2C%20%E8%BD%AE%E5%88%B0%E4%B8%A4%E6%9D%A1%E5%85%B3%E9%94%AE%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20RES%7B%22%E6%89%80%E9%9C%80%E8%B5%84%E6%BA%90%E7%A9%BA%E9%97%B2%3F%22%7D%0A%20%20RES%20--%3E%7C%22%E6%98%AF%22%7C%20FIRE%5B%22%E6%9C%AC%E6%8B%8D%E5%8F%91%E5%B0%84%22%5D%0A%20%20RES%20--%3E%7C%22%E5%90%A6%3A%20%E4%B9%98%E6%B3%95%E5%99%A8%E5%8F%AA%E6%9C%89%E4%B8%80%E4%B8%AA%22%7C%20FILL%5B%22%E6%8F%92%E7%8B%AC%E7%AB%8B%E6%8C%87%E4%BB%A4%E5%A1%AB%E6%A7%BD%E6%88%96%E7%AD%89%E5%BE%85%22%5D%0A%20%20FILL%20--%3E%20GROW%5B%22%E6%80%BB%E6%8B%8D%E6%95%B0%E8%B6%85%E8%BF%87%E4%B8%8B%E7%95%8C%22%5D%0A%20%20FIRE%20--%3E%20NEXT%5B%22%E6%9B%B4%E6%96%B0%E5%B0%B1%E7%BB%AA%E8%A1%A8%2C%20%E9%80%89%E4%B8%8B%E4%B8%80%E4%B8%AA%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：初学者容易以为关键路径上的指令必须一格挨一格连续发射。实际上中间的空槽可以塞进与它无关的独立指令填缝——这正是表调度的本职；「关键」说的是不能被推迟，不是「独占流水线」。</span></p><p>PGO：热块更值得按精确延迟模型排。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写电路 STA。后课默认：高度驱动表调度。下一课树匹配指令选择：调度前还要先选对指令。</p><p>也不把关键路径当项目管理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>块内下界 = DAG 关键路径；高度优先逼近它。</li><li>资源约束使下界不可达。</li><li>与模调度的 RecMII 同源。</li><li>出处：Hennessy and Gross；龙书；对照组成课关键路径（不同对象）。</li></ul>',7))])}const S=A(p,[["render",c]]);export{T as __pageData,S as default};
